import unittest
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_area_with_positive_integers(self):
        self.assertAlmostEqual(triangle_area(5, 3), 7.5)

    def test_area_with_positive_floats(self):
        self.assertAlmostEqual(triangle_area(4.2, 2.5), 5.25)

    def test_area_with_zero_side(self):
        self.assertEqual(triangle_area(0, 10), 0.0)

    def test_area_with_zero_height(self):
        self.assertEqual(triangle_area(10, 0), 0.0)

    def test_area_with_negative_side(self):
        self.assertAlmostEqual(triangle_area(-5, 3), -7.5)

    def test_area_with_negative_height(self):
        self.assertAlmostEqual(triangle_area(5, -3), -7.5)

    def test_area_with_both_negative(self):
        self.assertAlmostEqual(triangle_area(-4, -6), 12.0)

    def test_area_return_type_is_float(self):
        result = triangle_area(7, 3)
        self.assertIsInstance(result, float)

    def test_area_with_large_numbers(self):
        large = 1e12
        result = triangle_area(large, large)
        self.assertTrue(result > 0)
        self.assertTrue(result < float('inf'))

    def test_area_with_string_input_a(self):
        with self.assertRaises(TypeError):
            triangle_area("5", 3)

    def test_area_with_string_input_h(self):
        with self.assertRaises(TypeError):
            triangle_area(5, "3")

    def test_area_with_none_input_a(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 3)

    def test_area_with_none_input_h(self):
        with self.assertRaises(TypeError):
            triangle_area(5, None)

    def test_area_with_list_input(self):
        with self.assertRaises(TypeError):
            triangle_area([5], 3)

    def test_area_with_tuple_input(self):
        with self.assertRaises(TypeError):
            triangle_area(5, (3,))

    def test_area_with_dict_input(self):
        with self.assertRaises(TypeError):
            triangle_area({"a": 5}, 3)

    def test_area_with_custom_object_input(self):
        class Dummy:
            pass
        with self.assertRaises(TypeError):
            triangle_area(Dummy(), 3)

    def test_area_boundary_case_small_positive(self):
        self.assertAlmostEqual(triangle_area(1e-10, 1e-10), 5e-21)

    def test_area_boundary_case_small_negative(self):
        self.assertAlmostEqual(triangle_area(-1e-10, -1e-10), 5e-21)

    def test_area_boundary_case_negative_small_positive(self):
        self.assertAlmostEqual(triangle_area(-1e-10, 1e-10), -5e-21)

    def test_area_boundary_case_positive_small_negative(self):
        self.assertAlmostEqual(triangle_area(1e-10, -1e-10), -5e-21)

    def test_area_no_side_and_height_provided(self):
        with self.assertRaises(TypeError):
            triangle_area()

    def test_area_too_many_arguments(self):
        with self.assertRaises(TypeError):
            triangle_area(5, 3, 2)

if __name__ == '__main__':
    unittest.main()
